mapper.select:
select info.author,info.speaker,info.tips,info.infoId,info.title,ca.name,ca.parent_id,info.addInfoTime,info.read_count,info.state,info.thumbnail_url,info.category_id,info.typeid,info.infoId,info.video_url,info.user_code , CASE WHEN ( SELECT count(1) FROM yh_user_reginfo reg WHERE reg.Org_Code LIKE CONCAT('%', #{orgCode2}, '%') AND reg.user_code = info.user_code ) THEN '1' ELSE '0' END 'quanxian'
, (select count(*) from yh_health_lecture_comment where lectureInfoId=info.infoId) as num, (select count(*) from yh_health_lecture_watch t1,yh_health_lecture_info t2 where t1.class_id = t2.infoId and t1.class_id= info.infoId) as watch from yh_health_lecture_info info left join yh_health_lecture_category ca on info.category_id=ca.categoryId left join yh_org_tree as org on info.user_code=org.User_Code
( org.user_code = #{orgCode} OR org.Super_Org_Code LIKE concat( '', ( SELECT Org_code FROM yh_org_tree WHERE user_code = #{orgCode} ), '%' ) )
AND ( info.title like CONCAT('%',#{title},'%' ) )
AND ( info.author like CONCAT('%',#{author},'%' ) )
and info.category_id = #{categoryId,jdbcType=INTEGER}
${superaddition}
and ca.name is null
and typeid=#{typeid}
order by info.addInfoTime desc LIMIT #{page},#{limit}

	    select count(*) from  yh_health_lecture_info info
		left join yh_health_lecture_category ca on  info.category_id=ca.categoryId
      left join yh_org_tree as org on info.user_code=org.User_Code


          (
          org.user_code = #{orgCode}
          OR org.Super_Org_Code LIKE concat(
          '',
          (
          SELECT
          Org_code
          FROM
          yh_org_tree
          WHERE
          user_code = #{orgCode}
          ),
          '%'
          )
          )


			AND
			(
				info.title like CONCAT('%',#{title},'%' )
			)



			AND
			(
				info.author like CONCAT('%',#{author},'%' )
			)




			and
			info.category_id = #{categoryId,jdbcType=INTEGER}


			${superaddition}


			and ca.name is null


			and typeid=#{typeid}


		order by info.addInfoTime desc
